mkuse!{use rustc_index :: Idx ;}
mkuse!{use rustc_index :: bit_set :: { DenseBitSet , MixedBitSet } ;}
mkuse!{use crate :: framework :: BitSetExt ;}
mkitem!{mktrait!{# [doc = " A [partially ordered set][poset] that has a [least upper bound][lub] for any pair of elements"] # [doc = " in the set."] # [doc = ""] # [doc = " [lub]: https://en.wikipedia.org/wiki/Infimum_and_supremum"] # [doc = " [poset]: https://en.wikipedia.org/wiki/Partially_ordered_set"] pub trait JoinSemiLattice : Eq { # [doc = " Computes the least upper bound of two elements, storing the result in `self` and returning"] # [doc = " `true` if `self` has changed."] # [doc = ""] # [doc = " The lattice join operator is abbreviated as `∨`."] fn join (& mut self , other : & Self) -> bool ; }}}
mkitem!{mktrait!{# [doc = " A set that has a \"bottom\" element, which is less than or equal to any other element."] pub trait HasBottom { const BOTTOM : Self ; fn is_bottom (& self) -> bool ; }}}
mkitem!{mktrait!{# [doc = " A set that has a \"top\" element, which is greater than or equal to any other element."] pub trait HasTop { const TOP : Self ; }}}
mkitem!{mkimpl!{# [doc = " A `DenseBitSet` represents the lattice formed by the powerset of all possible values of the"] # [doc = " index type `T` ordered by inclusion. Equivalently, it is a tuple of \"two-point\" lattices, one"] # [doc = " for each possible value of `T`."] impl < T : Idx > JoinSemiLattice for DenseBitSet < T > { fn join (& mut self , other : & Self) -> bool { self . union (other) } }}}
mkitem!{mkimpl!{impl < T : Idx > JoinSemiLattice for MixedBitSet < T > { fn join (& mut self , other : & Self) -> bool { self . union (other) } }}}
mkitem!{mkenum!{# [doc = " Extends a type `T` with top and bottom elements to make it a partially ordered set in which no"] # [doc = " value of `T` is comparable with any other."] # [doc = ""] # [doc = " A flat set has the following [Hasse diagram]:"] # [doc = ""] # [doc = " ```text"] # [doc = "          top"] # [doc = "  / ... / /  \\ \\ ... \\"] # [doc = " all possible values of `T`"] # [doc = "  \\ ... \\ \\  / / ... /"] # [doc = "         bottom"] # [doc = " ```"] # [doc = ""] # [doc = " [Hasse diagram]: https://en.wikipedia.org/wiki/Hasse_diagram"] # [derive (Clone , Copy , Debug , PartialEq , Eq)] pub enum FlatSet < T > { Bottom , Elem (T) , Top , }}}
mkitem!{mkimpl!{impl < T : Clone + Eq > JoinSemiLattice for FlatSet < T > { fn join (& mut self , other : & Self) -> bool { let result = match (& * self , other) { (Self :: Top , _) | (_ , Self :: Bottom) => return false , (Self :: Elem (a) , Self :: Elem (b)) if a == b => return false , (Self :: Bottom , Self :: Elem (x)) => Self :: Elem (x . clone ()) , _ => Self :: Top , } ; * self = result ; true } }}}
mkitem!{mkimpl!{impl < T > HasBottom for FlatSet < T > { const BOTTOM : Self = Self :: Bottom ; fn is_bottom (& self) -> bool { matches ! (self , Self :: Bottom) } }}}
mkitem!{mkimpl!{impl < T > HasTop for FlatSet < T > { const TOP : Self = Self :: Top ; }}}
mkitem!{mkenum!{# [doc = " Extend a lattice with a bottom value to represent an unreachable execution."] # [doc = ""] # [doc = " The only useful action on an unreachable state is joining it with a reachable one to make it"] # [doc = " reachable. All other actions, gen/kill for instance, are no-ops."] # [derive (PartialEq , Eq , Debug)] pub enum MaybeReachable < T > { Unreachable , Reachable (T) , }}}
mkitem!{mkimpl!{impl < T > MaybeReachable < T > { pub fn is_reachable (& self) -> bool { matches ! (self , MaybeReachable :: Reachable (_)) } }}}
mkitem!{mkimpl!{impl < S > MaybeReachable < S > { # [doc = " Return whether the current state contains the given element. If the state is unreachable,"] # [doc = " it does no contain anything."] pub fn contains < T > (& self , elem : T) -> bool where S : BitSetExt < T > , { match self { MaybeReachable :: Unreachable => false , MaybeReachable :: Reachable (set) => set . contains (elem) , } } }}}
mkitem!{mkimpl!{impl < T , S : BitSetExt < T > > BitSetExt < T > for MaybeReachable < S > { fn contains (& self , elem : T) -> bool { self . contains (elem) } }}}
mkitem!{mkimpl!{impl < V : Clone > Clone for MaybeReachable < V > { fn clone (& self) -> Self { match self { MaybeReachable :: Reachable (x) => MaybeReachable :: Reachable (x . clone ()) , MaybeReachable :: Unreachable => MaybeReachable :: Unreachable , } } fn clone_from (& mut self , source : & Self) { match (& mut * self , source) { (MaybeReachable :: Reachable (x) , MaybeReachable :: Reachable (y)) => { x . clone_from (y) ; } _ => * self = source . clone () , } } }}}
mkitem!{mkimpl!{impl < T : JoinSemiLattice + Clone > JoinSemiLattice for MaybeReachable < T > { fn join (& mut self , other : & Self) -> bool { match (& mut * self , & other) { (_ , MaybeReachable :: Unreachable) => false , (MaybeReachable :: Unreachable , _) => { * self = other . clone () ; true } (MaybeReachable :: Reachable (this) , MaybeReachable :: Reachable (other)) => this . join (other) , } } }}}